import { showModal } from '@ui-kit/Modal';

import SelectRouteModalContent from './SelectRouteModalContent';
import { IRouteListItem } from '../@services/routes.service';

export const selectOneRoute = (): Promise<IRouteListItem> =>
  new Promise((res) => {
    showModal({
      title: 'Выбор маршрута',
      children: (clos) => (
        <SelectRouteModalContent
          onSelect={(s) => {
            res(s);
            clos();
          }}
        />
      ),
    });
  });
