import React from 'react';

import PageLoader from '@components/PageLoader';
import Empty from '@ui-kit/Empty';
import PohInput, { InputTypes } from '@ui-kit/Input';
import PohList from '@ui-kit/List';

import RoutesListItem from './RoutesListItem';
import { getAllRoutes, IRouteListItem } from '../@services/routes.service';

interface ISelectRouteModalContentProps {
  onSelect: (sel: IRouteListItem) => void;
}

const SelectRouteModalContent: React.FC<ISelectRouteModalContentProps> = ({ onSelect }) => {
  const [data, setData] = React.useState<IRouteListItem[]>([]);
  const [isLoading, setIsLoading] = React.useState(true);
  const [q, setQ] = React.useState('');

  React.useEffect(() => {
    getAllRoutes()
      .then(setData)
      .finally(() => setIsLoading(false));
  }, []);

  const filtered = data.filter((d) => !q.length || JSON.stringify(d).includes(q));

  return (
    <>
      <PohInput
        type={InputTypes.search}
        value={q}
        onChange={setQ}
        placeholder="Найти"
        className="mb-2"
      />
      <div style={{ overflowY: 'auto', maxHeight: '48vh' }}>
        {isLoading && <PageLoader />}
        {!filtered.length && <Empty>Нет маршрутов</Empty>}
        {!!filtered.length && (
          <PohList
            data={filtered.map((x) => ({
              key: x.id,
              action: true,
              onClick: () => onSelect(x),
              content: <RoutesListItem data={x} />,
            }))}
          />
        )}
      </div>
    </>
  );
};
export default SelectRouteModalContent;
